// dbVarsRequiringRestart lists DB variables that cause BIG-IP service restarts
// when modified. These variables require retry logic to handle transient API
// unavailability during the restart period.
var dbVarsRequiringRestart = map[string]bool{
	"provision.extramb":           true,
	"provision.restjavad.extramb": true,
}

// doesDbVarRequireRestart checks if a DB variable causes service restarts
func doesDbVarRequireRestart(name string) bool {
	return dbVarsRequiringRestart[name]
}

// isValidIPAddress validates IPv4 and IPv6 addresses
func isValidIPAddress(ip string) bool {
	if ip == "::" {
		return true
	}
	return net.ParseIP(ip) != nil
}

// validateEnum validates that value is one of the allowed string values
func validateEnum(name string, allowedValues ...string) func(interface{}) error {
	return func(val interface{}) error {
		s := fmt.Sprint(val)
		for _, allowed := range allowedValues {
			if s == allowed {
				return nil
			}
		}
		return fmt.Errorf("%s must be one of: %s", name, strings.Join(allowedValues, " "))
	}
}

// validateIntRange validates integer is within min/max range (for signed integers)
func validateIntRange(name string, min, max int64) func(interface{}) error {
	return func(val interface{}) error {
		v := fmt.Sprint(val)
		num, err := strconv.ParseInt(v, 10, 64)
		if err != nil {
			return fmt.Errorf("%s must be an integer", name)
		}
		if num < min || num > max {
			return fmt.Errorf("%s must be between %d and %d", name, min, max)
		}
		return nil
	}
}

// validateUintRange validates integer is within min/max range (for unsigned integers)
// Used for ranges that exceed int64 max (9223372036854775807) or need full uint64 range
func validateUintRange(name string, min, max uint64) func(interface{}) error {
	return func(val interface{}) error {
		v := fmt.Sprint(val)
		num, err := strconv.ParseUint(v, 10, 64)
		if err != nil {
			return fmt.Errorf("%s must be a positive integer", name)
		}
		if num < min || num > max {
			return fmt.Errorf("%s must be between %d and %d", name, min, max)
		}
		return nil
	}
}

// validatePositiveInt validates integer is >= 0
func validatePositiveInt(name string) func(interface{}) error {
	return func(val interface{}) error {
		v := fmt.Sprint(val)
		num, err := strconv.Atoi(v)
		if err != nil {
			return fmt.Errorf("%s must be an integer", name)
		}
		if num < 0 {
			return fmt.Errorf("%s must be a positive integer", name)
		}
		return nil
	}
}

// validateString validates value is a string type
func validateString(name string) func(interface{}) error {
	return func(val interface{}) error {
		if _, ok := val.(string); !ok {
			return fmt.Errorf("%s value must be a string", name)
		}
		return nil
	}
}

// validateIPAddress validates IPv4 or IPv6 address
func validateIPAddress(name string) func(interface{}) error {
	return func(val interface{}) error {
		s := fmt.Sprint(val)
		if !isValidIPAddress(s) {
			return fmt.Errorf("%s must be a valid IPv4 or IPv6 address", name)
		}
		return nil
	}
}

